import numpy as np
import xarray as xr
from pyresample import resampler

class MockResampler(resampler.BaseResampler):
    def __init__(self, source_geo, target_geo):
        super().__init__(source_geo, target_geo)

    def _geometries_are_the_same(self):
        return True # Simulate same geometry

    def precompute(self, **kwargs):
        return "cache_id"

    def compute(self, data, **kwargs):
        # Return data modified to show resampling happened
        return data + 1

# Setup data
data = xr.DataArray(np.ones((10, 10)), dims=('y', 'x'))

# Mock geometries
class MockGeo:
    def update_hash(self, the_hash=None):
        return the_hash if the_hash else "hash"

geo = MockGeo()

res = MockResampler(geo, geo)

print("Testing default behavior (should skip resampling)...")
result = res.resample(data)
if np.all(result == 1):
    print("Default behavior: Skipped resampling as expected.")
else:
    print("Default behavior: Resampled unexpectedly!")
    exit(1)

print("Testing skip_if_same_geometry=False (should force resampling)...")
try:
    # This should fail on the current version because it will still skip
    # and it might also raise a TypeError if skip_if_same_geometry is not accepted by resample
    result = res.resample(data, skip_if_same_geometry=False)
    if np.all(result == 2):
        print("Forced resampling: Worked as expected.")
    else:
        print("Forced resampling: Still skipped resampling!")
        exit(1)
except Exception as e:
    print(f"Forced resampling: Failed with exception: {e}")
    exit(1)
EOF
